  SELECT ders_kodu, ogr_no, notu,
         ROW_NUMBER() OVER (PARTITION BY ders_kodu ORDER BY notu DESC) AS rn
  FROM kayit WHERE notu IS NOT NULL
) WHERE rn = 1 ORDER BY ders_kodu;

